#!/usr/bin/env node
/**
 * Record the bot-path goldens (review item 8).
 *
 *   node tests/fixtures/bot-golden/record.mjs [--force]
 *
 * Writes tests/fixtures/bot-golden/contain-plans.json and
 * egress-transcripts.json from buildContainCases() and
 * buildEgressTranscripts() (cases.mjs). These files are recorded ONCE at the
 * base sha and are never regenerated by a later PR; an existing file is
 * refused unless --force is passed, because regenerating it would turn a
 * proven-identical refactor into a rubber stamp.
 */
import { existsSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { buildContainCases, buildEgressTranscripts } from "./cases.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const force = process.argv.includes("--force");

const targets = [
  { file: join(here, "contain-plans.json"), build: async () => buildContainCases() },
  { file: join(here, "egress-transcripts.json"), build: async () => buildEgressTranscripts() },
];

const existing = targets.filter((t) => existsSync(t.file));
if (existing.length && !force) {
  for (const t of existing) process.stderr.write(`refusing to overwrite ${t.file}\n`);
  process.stderr.write("these goldens are recorded once at the base sha; pass --force only to record them the first time\n");
  process.exit(1);
}

for (const t of targets) {
  const data = await t.build();
  writeFileSync(t.file, JSON.stringify(data, null, 2) + "\n");
  process.stdout.write(`wrote ${t.file}\n`);
}